from ircu import consts
from ircu.user import User


def int_to_base64(n, count):
    buf = ''
    while count > 0:
        count -= 1
        buf = consts.BASE64_INT_TO_NUM[n & consts.BASE64_NUMNICKMASK] + buf
        n >>= consts.BASE64_NUMNICKLOG
    return buf


def base64_to_int(s):
    n = 0
    for ii in range(0, len(s)):
        n = n << 6
        n += consts.BASE64_NUM_TO_INT[ord(s[ii])]
    return n


def user_to_num(user):
    """Convert a User object to numeric identifier"""
    return hex(user.uid)[-6:].upper()

def num_to_user(num):
    """Convert a numeric identifier to a User object.
    If no user corresponds to the identifier, a blank
    User object is returned.
    """
    num = int(num, 16)
    try:
        return User(user_id=num)
    except ValueError:
        return User()

